```cpp
#include <iostream>

const int* find_value(const int* first, const int* last, int value) {
    for (; first != last; ++first)
        if (*first == value) return first;
    return last;
}

int main() {
    int arr[] = {4, 8, 15, 16};
    std::cout << (find_value(arr, arr + 4, 15) - arr) << '\n';  // 2
}
```
Subtracting two pointers into the same array gives the distance in elements.

