reverse_range(a, a + 5);
assert(a[0] == 5 && a[1] == 4 && a[2] == 3 && a[3] == 2 && a[4] == 1);
int b[] = {1, 2};
reverse_range(b, b + 2);
assert(b[0] == 2 && b[1] == 1);
int c[] = {7};
reverse_range(c, c + 1);
reverse_range(c, c);
assert(c[0] == 7);

