```cpp
#include <iostream>

int* max_element_ptr(int* first, int* last) {
    if (first == last) return nullptr;
    int* best = first;
    for (int* p = first + 1; p != last; ++p)
        if (*p > *best) best = p;
    return best;
}

int main() {
    int a[] = {3, 9, 2, 9};
    *max_element_ptr(a, a + 4) = 0;
    for (int x : a) std::cout << x << ' ';
    std::cout << '\n';  // 3 0 2 9
}
```

