```cpp
#include <iostream>
#include <vector>

struct Node {
    int value;
    Node* next;
};

Node* build(const std::vector<int>& vals) {
    Node* head = nullptr;
    for (auto it = vals.rbegin(); it != vals.rend(); ++it) head = new Node{*it, head};
    return head;
}

std::vector<int> to_vector(const Node* head) {
    std::vector<int> out;
    for (; head != nullptr; head = head->next) out.push_back(head->value);
    return out;
}

void free_list(Node* head) {
    while (head) {
        Node* next = head->next;
        delete head;
        head = next;
    }
}

Node* middle(Node* head) {
    Node* slow = head;
    Node* fast = head;
    while (fast && fast->next) {
        slow = slow->next;
        fast = fast->next->next;
    }
    return slow;
}

int main() {
    Node* h = build({1, 2, 3, 4, 5});
    std::cout << middle(h)->value << '\n';
    free_list(h);
}
```
Fast covers twice the distance, so when it reaches the end, slow has covered half. You'll reuse this on Friday (Reorder List).

tasks.tests:
