assert(middle(a)->value == 3);
Node* b = build({1, 2, 3, 4});
assert(middle(b)->value == 3);
Node* c = build({9});
assert(middle(c)->value == 9);
assert(middle(nullptr) == nullptr);
free_list(a); free_list(b); free_list(c);

