import numpy as np


def bayes_update(belief, likelihood):
    post = np.asarray(belief, dtype=float) * np.asarray(likelihood, dtype=float)
    return post / post.sum()


def sense_likelihood(world, reading, p_hit, p_miss):
    return np.where(np.asarray(world) == reading, p_hit, p_miss)


world = ['door', 'wall', 'door', 'wall', 'wall']
b = bayes_update(np.full(5, 0.2), sense_likelihood(world, 'door', 0.8, 0.1))
print(b.round(3))
```

```python
import numpy as np


def bayes_update(belief, likelihood):
    post = np.asarray(belief, dtype=float) * np.asarray(likelihood, dtype=float)
    return post / post.sum()


def sense_likelihood(world, reading, p_hit, p_miss):
    return np.where(np.asarray(world) == reading, p_hit, p_miss)


def localize(world, readings, p_hit, p_miss):
    belief = np.full(len(world), 1 / len(world))
    for i, r in enumerate(readings):
        belief = bayes_update(belief, sense_likelihood(world, r, p_hit, p_miss))
        if i < len(readings) - 1:
            belief = np.roll(belief, 1)
    return belief


world = ['door', 'wall', 'door', 'wall', 'wall']
b = localize(world, ['door', 'wall', 'door'], 0.8, 0.1)
print(b.round(3), int(b.argmax()))
```
Cell 2 is the only place where the last three cells visited read door, wall, door. Other paths need at least one sensor error, which the likelihoods make unlikely.

```python
import numpy as np


def bayes_update(belief, likelihood):
    post = np.asarray(belief, dtype=float) * np.asarray(likelihood, dtype=float)
    return post / post.sum()


def sense_likelihood(world, reading, p_hit, p_miss):
    return np.where(np.asarray(world) == reading, p_hit, p_miss)


def localize(world, readings, p_hit, p_miss):
    belief = np.full(len(world), 1 / len(world))
    for i, r in enumerate(readings):
        belief = bayes_update(belief, sense_likelihood(world, r, p_hit, p_miss))
        if i < len(readings) - 1:
            belief = np.roll(belief, 1)
    return belief


def simulate_localization(world, target, p_correct, n, seed=0):
    rng = np.random.default_rng(seed)
    other = {'door': 'wall', 'wall': 'door'}
    matches = ends_at_2 = 0
    for _ in range(n):
        cell = int(rng.integers(len(world)))
        readings = []
        for step in range(len(target)):
            label = world[cell]
            readings.append(label if rng.random() < p_correct else other[label])
            if step < len(target) - 1:
                cell = (cell + 1) % len(world)
        if readings == target:
            matches += 1
            ends_at_2 += cell == 2
    return ends_at_2 / matches


world = ['door', 'wall', 'door', 'wall', 'wall']
target = ['door', 'wall', 'door']
print(round(simulate_localization(world, target, 0.85, 20_000), 3),
      round(float(localize(world, target, 0.85, 0.15)[2]), 3))
```
The two numbers agree because the filter computes exactly the conditional frequency the simulation counts.

```cpp
#include <cstddef>
#include <iostream>
#include <stdexcept>
#include <vector>

class IntList {
public:
    IntList() = default;
    ~IntList() { clear(); }
    IntList(const IntList&) = delete;
    IntList& operator=(const IntList&) = delete;

    void push_front(int v) {
        head_ = new Node{v, head_};
        if (!tail_) tail_ = head_;
        ++size_;
    }
    void push_back(int v) {
        Node* n = new Node{v, nullptr};
        if (tail_) tail_->next = n; else head_ = n;
        tail_ = n;
        ++size_;
    }
    int pop_front() {
        if (!head_) throw std::out_of_range("pop_front on empty list");
        Node* old = head_;
        int v = old->value;
        head_ = old->next;
        if (!head_) tail_ = nullptr;
        delete old;
        --size_;
        return v;
    }
    int front() const {
        if (!head_) throw std::out_of_range("front on empty list");
        return head_->value;
    }
    int back() const {
        if (!tail_) throw std::out_of_range("back on empty list");
        return tail_->value;
    }
    bool contains(int v) const {
        for (Node* p = head_; p; p = p->next)
            if (p->value == v) return true;
        return false;
    }
    bool remove_first(int v) {
        Node dummy{0, head_};
        for (Node* p = &dummy; p->next; p = p->next) {
            if (p->next->value == v) {
                Node* victim = p->next;
                p->next = victim->next;
                if (victim == tail_) tail_ = (p == &dummy) ? nullptr : p;
                delete victim;
                head_ = dummy.next;
                --size_;
                return true;
            }
        }
        return false;
    }
    std::vector<int> to_vector() const {
        std::vector<int> out;
        for (Node* p = head_; p; p = p->next) out.push_back(p->value);
        return out;
    }
    std::size_t size() const { return size_; }
    bool empty() const { return size_ == 0; }
    void clear() {
        while (head_) {
            Node* next = head_->next;
            delete head_;
            head_ = next;
        }
        tail_ = nullptr;
        size_ = 0;
    }

private:
    struct Node {
        int value;
        Node* next;
    };
    Node* head_ = nullptr;
    Node* tail_ = nullptr;
    std::size_t size_ = 0;
};

int main() {
    IntList l;
    l.push_back(1);
    l.push_back(2);
    l.remove_first(2);
    l.push_back(3);
    for (int v : l.to_vector()) std::cout << v << ' ';
    std::cout << '\n';
}
```

