#include <cstddef>
#include <stdexcept>

class IntStack {
public:
    explicit IntStack(std::size_t capacity) : capacity_(capacity), data_(new int[capacity]) {}
    ~IntStack() { delete[] data_; }
    IntStack(const IntStack&) = delete;
    IntStack& operator=(const IntStack&) = delete;

    bool push(int v) {
        if (size_ == capacity_) return false;
        data_[size_++] = v;
        return true;
    }
    int pop() {
        if (size_ == 0) throw std::out_of_range("pop on empty stack");
        return data_[--size_];
    }
    std::size_t size() const { return size_; }
    bool empty() const { return size_ == 0; }
private:
    std::size_t capacity_;
    std::size_t size_ = 0;
    int* data_;
};

int main() {
    IntStack s(2);
    s.push(1);
    return s.pop() == 1 ? 0 : 1;
}
```
Deleting the copy operations is the honest choice when copying isn't needed: the compiler now refuses `IntStack b = a;` instead of silently producing a double free.

