```python
class ListNode:
    def __init__(self, val=0, next=None):
        self.val = val
        self.next = next


def build(values):
    head = None
    for v in reversed(values):
        head = ListNode(v, head)
    return head


def to_list(head):
    out = []
    while head:
        out.append(head.val)
        head = head.next
    return out


def build_with_cycle(values, pos):
    head = build(values)
    if pos < 0 or head is None:
        return head
    nodes = []
    node = head
    while node:
        nodes.append(node)
        node = node.next
    nodes[-1].next = nodes[pos]
    return head


def has_cycle_set(head):
    seen = set()
    while head:
        if head in seen:
            return True
        seen.add(head)
        head = head.next
    return False


def has_cycle(head):
    slow = fast = head
    while fast and fast.next:
        slow = slow.next
        fast = fast.next.next
        if slow is fast:
            return True
    return False


print(has_cycle(build_with_cycle([3, 2, 0, -4], 1)), has_cycle(build([1, 2])))
```
Why they must meet: once both are inside the cycle, the gap between them shrinks by exactly one node per step (fast gains 1 on slow), so it reaches 0 within one lap; it can't jump over.

