    a.push_back(1);
    IntList b = a;            // copy
    b.push_back(2);
    IntList c = std::move(b); // move: b is now empty
    std::cout << a.size() << ' ' << b.size() << ' ' << c.size() << '\n';  // 1 0 2
}
