```python
import numpy as np
from collections import defaultdict

VALUES, PROBS = [5, 6, 7], [0.2, 0.5, 0.3]


def sample_discrete(values, probs, n, seed=0):
    rng = np.random.default_rng(seed)
    idx = np.searchsorted(np.cumsum(probs), rng.random(n), side='right')
    return np.asarray(values)[np.minimum(idx, len(values) - 1)]


def diff_pmf_exact():
    out = defaultdict(float)
    for a, pa in zip(VALUES, PROBS):
        for b, pb in zip(VALUES, PROBS):
            out[a - b] += pa * pb
    return dict(out)


def diff_pmf_sim(n, seed=0):
    d = sample_discrete(VALUES, PROBS, n, seed) - sample_discrete(VALUES, PROBS, n, seed + 1)
    vals, counts = np.unique(d, return_counts=True)
    return {int(v): c / n for v, c in zip(vals, counts)}


print(round(diff_pmf_exact()[0], 3), round(diff_pmf_sim(100_000)[0], 3))
```
Two identical, perfectly matched wheels still disagree by a tick in most 100 ms windows: 62% of the time. A controller that corrects on every single-window difference just chases noise. Accumulate ticks over longer periods (or total ticks since start), which is what Thursday's prep does.

