#include <cstddef>
#include <iostream>
#include <stdexcept>
#include <utility>
#include <string>
#include <vector>

class IntList {
public:
    IntList() = default;
    ~IntList() { clear(); }
    IntList(const IntList& other) {
        for (Node* p = other.head_; p; p = p->next) push_back(p->value);
    }
    IntList(IntList&& other) noexcept
        : head_(other.head_), tail_(other.tail_), size_(other.size_) {
        other.head_ = other.tail_ = nullptr;
        other.size_ = 0;
    }
    IntList& operator=(IntList other) noexcept {   // copy-and-swap: covers copy and move assignment
        swap(other);
        return *this;
    }
    void swap(IntList& other) noexcept {
        std::swap(head_, other.head_);
        std::swap(tail_, other.tail_);
        std::swap(size_, other.size_);
    }

    void push_front(int v) {
        head_ = new Node{v, head_};
        if (!tail_) tail_ = head_;
        ++size_;
    }
    void push_back(int v) {
        Node* n = new Node{v, nullptr};
        if (tail_) tail_->next = n; else head_ = n;
        tail_ = n;
        ++size_;
    }
    int pop_front() {
        if (!head_) throw std::out_of_range("pop_front on empty list");
        Node* old = head_;
        int v = old->value;
        head_ = old->next;
        if (!head_) tail_ = nullptr;
        delete old;
        --size_;
        return v;
    }
    int front() const {
        if (!head_) throw std::out_of_range("front on empty list");
        return head_->value;
    }
    int back() const {
        if (!tail_) throw std::out_of_range("back on empty list");
        return tail_->value;
    }
    bool contains(int v) const {
        for (Node* p = head_; p; p = p->next)
            if (p->value == v) return true;
        return false;
    }
    bool remove_first(int v) {
        Node dummy{0, head_};
        for (Node* p = &dummy; p->next; p = p->next) {
            if (p->next->value == v) {
                Node* victim = p->next;
                p->next = victim->next;
                if (victim == tail_) tail_ = (p == &dummy) ? nullptr : p;
                delete victim;
                head_ = dummy.next;
                --size_;
                return true;
            }
        }
        return false;
    }
    std::vector<int> to_vector() const {
        std::vector<int> out;
        for (Node* p = head_; p; p = p->next) out.push_back(p->value);
        return out;
    }
    std::size_t size() const { return size_; }
    bool empty() const { return size_ == 0; }
    void clear() {
        while (head_) {
            Node* next = head_->next;
            delete head_;
            head_ = next;
        }
        tail_ = nullptr;
        size_ = 0;
    }

private:
    struct Node {
        int value;
        Node* next;
    };
    Node* head_ = nullptr;
    Node* tail_ = nullptr;
    std::size_t size_ = 0;
};


class IntStack {
public:
    void push(int v) { list_.push_front(v); }
    int pop() {
        if (list_.empty()) throw std::out_of_range("pop on empty stack");
        return list_.pop_front();
    }
    int top() const {
        if (list_.empty()) throw std::out_of_range("top on empty stack");
        return list_.front();
    }
    std::size_t size() const { return list_.size(); }
    bool empty() const { return list_.empty(); }

private:
    IntList list_;   // composition: a stack *has* a list
};

bool balanced(const std::string& s) {
    IntStack st;
    for (char c : s) {
        if (c == '(' || c == '[' || c == '{') {
            st.push(c);
        } else if (c == ')' || c == ']' || c == '}') {
            char open = c == ')' ? '(' : c == ']' ? '[' : '{';
            if (st.empty() || st.pop() != open) return false;
        }
    }
    return st.empty();
}

int main() {
    std::cout << balanced("{[()()]}") << balanced("([)]") << '\n';  // 10
}
```

