```cpp
#include <memory>

int alive = 0;
struct Child;
struct Parent {
    std::shared_ptr<Child> child;
    Parent() { ++alive; }
    ~Parent() { --alive; }
};
struct Child {
    std::weak_ptr<Parent> parent;   // was shared_ptr<Parent>: that version leaks both
    Child() { ++alive; }
    ~Child() { --alive; }
};

int alive_after_scope() {
    {
        auto p = std::make_shared<Parent>();
        auto c = std::make_shared<Child>();
        p->child = c;
        c->parent = p;
    }
    return alive;
}

int main() { return alive_after_scope(); }
```
With two shared_ptrs, when the block ends each object still has one owner (the other object), so neither destructor runs. The weak_ptr doesn't count, so the Parent's count reaches zero, it destroys its `child` member, and the Child's count reaches zero too.

```python
class ListNode:
    def __init__(self, val=0, next=None):
        self.val = val
        self.next = next


def build(values):
    head = None
    for v in reversed(values):
        head = ListNode(v, head)
    return head


def to_list(head):
    out = []
    while head:
        out.append(head.val)
        head = head.next
    return out


def remove_nth_from_end(head, n):
    dummy = ListNode(0, head)
    lead = trail = dummy
    for _ in range(n + 1):
        lead = lead.next
    while lead:
        lead = lead.next
        trail = trail.next
    trail.next = trail.next.next
    return dummy.next


print(to_list(remove_nth_from_end(build([1, 2, 3, 4, 5]), 2)))
```

