    public:
        using iterator_category = std::forward_iterator_tag;
        using value_type = int;
        using difference_type = std::ptrdiff_t;
        using pointer = const int*;
        using reference = const int&;

        const_iterator() = default;
        explicit const_iterator(const Node* n) : node_(n) {}
        reference operator*() const { return node_->value; }
        const_iterator& operator++() { node_ = node_->next; return *this; }
        const_iterator operator++(int) { auto old = *this; node_ = node_->next; return old; }
        bool operator==(const const_iterator& o) const { return node_ == o.node_; }
        bool operator!=(const const_iterator& o) const { return node_ != o.node_; }
    private:
        const Node* node_ = nullptr;
    };
    const_iterator begin() const { return const_iterator(head_); }
    const_iterator end() const { return const_iterator(nullptr); }

    void reverse() {
        Node* prev = nullptr;
        Node* cur = head_;
        tail_ = head_;
        while (cur) {
            Node* next = cur->next;
            cur->next = prev;
            prev = cur;
            cur = next;
        }
        head_ = prev;
    }

private:
    Node* head_ = nullptr;
    Node* tail_ = nullptr;
    std::size_t size_ = 0;
};

int main() {
    IntList l;
    for (int v : {3, 1, 4, 1, 5}) l.push_back(v);
    l.reverse();
    for (int v : l) std::cout << v << ' ';                                       // 5 1 4 1 3
    std::cout << "| sum " << std::accumulate(l.begin(), l.end(), 0) << '\n';     // 14
    std::cout << (std::find(l.begin(), l.end(), 4) != l.end()) << '\n';          // 1
}
```

