```python
import numpy as np


def pearson_r(x, y):
    x, y = np.asarray(x, float), np.asarray(y, float)
    dx, dy = x - x.mean(), y - y.mean()
    return (dx * dy).sum() / np.sqrt((dx ** 2).sum() * (dy ** 2).sum())


def fit_line(x, y):
    x, y = np.asarray(x, float), np.asarray(y, float)
    dx, dy = x - x.mean(), y - y.mean()
    b1 = (dx * dy).sum() / (dx ** 2).sum()
    return y.mean() - b1 * x.mean(), b1


def check_invariance(x, y):
    x, y = np.asarray(x, float), np.asarray(y, float)
    cases = {"original": (x, y), "y_doubled": (x, 2 * y), "x_rescaled": (10 * x + 3, y)}
    return {k: (pearson_r(a, b), fit_line(a, b)[1]) for k, (a, b) in cases.items()}


for k, (r, b1) in check_invariance([1, 2, 3, 4, 5], [2, 4, 5, 4, 7]).items():
    print(k, round(r, 3), round(b1, 3))
```

```cpp
#include <algorithm>
#include <cstddef>
#include <iostream>
#include <iterator>
#include <memory>
#include <numeric>
#include <stdexcept>
#include <utility>
#include <vector>

class IntList {
    struct Node {
        int value;
        std::unique_ptr<Node> next;   // each node owns the next one
    };

public:
    IntList() = default;
    ~IntList() { clear(); }                       // iterative: no deep recursion
    IntList(const IntList& other) {
        for (const Node* p = other.head_.get(); p; p = p->next.get()) push_back(p->value);
    }
    IntList(IntList&& other) noexcept
        : head_(std::move(other.head_)), tail_(other.tail_), size_(other.size_) {
        other.tail_ = nullptr;
        other.size_ = 0;
    }
    IntList& operator=(IntList other) noexcept { swap(other); return *this; }
    void swap(IntList& other) noexcept {
        std::swap(head_, other.head_);
        std::swap(tail_, other.tail_);
        std::swap(size_, other.size_);
    }

    void push_front(int v) {
        auto n = std::make_unique<Node>(Node{v, std::move(head_)});
        head_ = std::move(n);
        if (!tail_) tail_ = head_.get();
        ++size_;
    }
    void push_back(int v) {
        auto n = std::make_unique<Node>(Node{v, nullptr});
        Node* raw = n.get();
        if (tail_) tail_->next = std::move(n); else head_ = std::move(n);
        tail_ = raw;                               // tail_ observes, it doesn't own
        ++size_;
    }
    int pop_front() {
        if (!head_) throw std::out_of_range("pop_front on empty list");
        int v = head_->value;
        head_ = std::move(head_->next);            // old head is deleted here
        if (!head_) tail_ = nullptr;
        --size_;
        return v;
    }
    int front() const {
        if (!head_) throw std::out_of_range("front on empty list");
        return head_->value;
    }
    int back() const {
        if (!tail_) throw std::out_of_range("back on empty list");
        return tail_->value;
    }
    bool contains(int v) const { return std::find(begin(), end(), v) != end(); }
    bool remove_first(int v) {
        std::unique_ptr<Node>* link = &head_;      // the owning pointer that points at the current node
        Node* prev = nullptr;
        while (*link) {
            if ((*link)->value == v) {
                if (link->get() == tail_) tail_ = prev;
                *link = std::move((*link)->next);
                --size_;
                return true;
            }
            prev = link->get();
            link = &(*link)->next;
        }
        return false;
    }
    void reverse() {
        std::unique_ptr<Node> prev;
        tail_ = head_.get();
        while (head_) {
            auto next = std::move(head_->next);
            head_->next = std::move(prev);
            prev = std::move(head_);
            head_ = std::move(next);
        }
        head_ = std::move(prev);
    }
    std::vector<int> to_vector() const { return std::vector<int>(begin(), end()); }
    std::size_t size() const { return size_; }
    bool empty() const { return size_ == 0; }
    void clear() {
        while (head_) head_ = std::move(head_->next);
        tail_ = nullptr;
        size_ = 0;
    }

    class const_iterator {
    public:
        using iterator_category = std::forward_iterator_tag;
        using value_type = int;
        using difference_type = std::ptrdiff_t;
        using pointer = const int*;
        using reference = const int&;
        const_iterator() = default;
        explicit const_iterator(const Node* n) : node_(n) {}
        reference operator*() const { return node_->value; }
        const_iterator& operator++() { node_ = node_->next.get(); return *this; }
        const_iterator operator++(int) { auto old = *this; ++*this; return old; }
        bool operator==(const const_iterator& o) const { return node_ == o.node_; }
        bool operator!=(const const_iterator& o) const { return node_ != o.node_; }
    private:
        const Node* node_ = nullptr;
    };
    const_iterator begin() const { return const_iterator(head_.get()); }
    const_iterator end() const { return const_iterator(nullptr); }

private:
    std::unique_ptr<Node> head_;
    Node* tail_ = nullptr;
    std::size_t size_ = 0;
};

int main() {
    IntList l;
    for (int i = 0; i < 300000; ++i) l.push_back(i);   // long list: clear() must not recurse
    l.reverse();
    std::cout << l.front() << ' ' << l.back() << ' ' << l.size() << '\n';
}
```
No `delete` anywhere: ownership is in the types.

